import itertools

def solve_game(n):
    # State: (alice_chosen, bob_chosen, turn)
    # turn 0: Alice, turn 1: Bob
    memo = {}

    def get_winner(a_chosen, b_chosen, turn):
        state = (tuple(sorted(a_chosen)), tuple(sorted(b_chosen)), turn)
        if state in memo:
            return memo[state]

        # All numbers chosen?
        if len(a_chosen) + len(b_chosen) == n:
            return 0 # Draw

        # Current player's turn
        current_chosen = a_chosen if turn == 0 else b_chosen
        other_chosen = b_chosen if turn == 0 else a_chosen

        possible_moves = []
        for i in range(1, n + 1):
            if i not in a_chosen and i not in b_chosen:
                # Rule (ii): cannot choose a number consecutive to any already chosen
                is_consecutive = False
                for chosen in current_chosen:
                    if abs(i - chosen) == 1:
                        is_consecutive = True
                        break
                if not is_consecutive:
                    possible_moves.append(i)

        if not possible_moves:
            # Current player cannot move, so they lose.
            # If turn 0 (Alice) loses, Bob wins (1). If turn 1 (Bob) loses, Alice wins (-1).
            return 1 if turn == 0 else -1

        # Current player wants to maximize their outcome:
        # Alice (turn 0) wants to maximize (Alice wins: -1, Draw: 0, Bob wins: 1)
        # Wait, Alice wants the outcome to be -1 (Alice wins).
        # Let's redefine: -1: Alice wins, 0: Draw, 1: Bob wins.
        # Alice (turn 0) wants to minimize the result.
        # Bob (turn 1) wants to maximize the result.

        if turn == 0:
            best_res = float('inf')
            for move in possible_moves:
                res = get_winner(a_chosen | {move}, b_chosen, 1)
                best_res = min(best_res, res)
            memo[state] = best_res
            return best_res
        else:
            best_res = float('-inf')
            for move in possible_moves:
                res = get_winner(a_chosen, b_chosen | {move}, 0)
                best_res = max(best_res, res)
            memo[state] = best_res
            return best_res

    return get_winner(set(), set(), 0)

